#include <bits/stdc++.h>
#define reg register
#define int long long
using namespace std;

inline int get_input() {
    int sign=1, val=0; char ch=getchar();
    while (ch<'0'||ch>'9') { if (ch=='-') sign=-1; ch=getchar(); }
    while (ch>='0'&&ch<='9') { val=val*10+ch-48; ch=getchar(); }
    return sign*val;
}

inline int min_value(reg int a, reg int b) { return a<b?a:b; }
inline int max_value(reg int a, reg int b) { return a>b?a:b; }

const int MAXN=2000010, MOD1=1000000007, MOD2=998244353, BASE=1000000;
int total_numbers, current_index, total_result, prefix_sums[10];
vector<int> buckets[10];

inline int mod_value(reg int x) { return (x%MOD2+MOD2)%MOD2; }

void generate(reg int start, reg int depth) {
    ++total_numbers;
    buckets[depth].push_back(mod_value(total_numbers - start));
    (total_result += buckets[depth].back()) %= MOD1;
    if (depth==6) return;
    for (reg int d=0; d<10; d++) generate(start*10+d, depth+1);
}

void process(reg int number) {
    if (number > n) return;
    if (number*BASE + (BASE-1) <= n && number*BASE*10 > n) {
        reg int prev_idx=total_numbers;
        for (reg int level=0, mult=1; level<=6; level++, mult*=10) {
            reg int size=buckets[level].size();
            reg int delta=mod_value(prev_idx - number*mult);
            reg int pos=lower_bound(buckets[level].begin(), buckets[level].end(), MOD2 - delta) - buckets[level].begin();
            total_result=(total_result + delta*size + prefix_sums[level] - MOD2*(size - pos))%MOD1;
            total_numbers+=size;
        }
        return;
    }
    ++total_numbers;
    total_result=(total_result + mod_value(total_numbers - number))%MOD1;
    for (reg int d=0; d<10; d++) process(number*10+d);
}

signed main() {
    n=get_input();
    generate(0,0);
    for (reg int i=0; i<=6; i++) sort(buckets[i].begin(), buckets[i].end());
    total_numbers=0;
    for (reg int i=1; i<=9; i++) process(i);
    printf("%lld", (total_result+MOD1)%MOD1);
    return 0;
}
